const request = require('supertest');
const assert = require('node:assert/strict');
const app = require('./app.js');
const expVer = parseInt(require('express/package.json').version.split('.')[0], 10);
assert.ok(expVer >= 5, 'Express >= 5 required');

async function runTests() {
    const resRoot = await request(app).get('/');
    assert.equal(resRoot.status, 200);

    const resNested = await request(app).get('/a/b');
    assert.equal(resNested.status, 200);
    assert.ok(Array.isArray(resNested.body.splat));
    assert.deepEqual(resNested.body.splat, ['a', 'b']);

    const resHealth = await request(app).get('/health');
    assert.equal(resHealth.status, 200);
    assert.equal(resHealth.text, 'healthy');
    console.log('ALL TESTS PASSED');
}
runTests().catch(err => { console.error(err); process.exit(1); });

